<?php defined( 'ABSPATH' ) || exit; ?>
<form class="pcr-form" method="post" enctype="multipart/form-data" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>" data-pcr-form>
    <input type="hidden" name="action" value="petish_customer_review_submit"><input type="hidden" name="product_id" value="<?php echo esc_attr( $product->get_id() ); ?>"><?php Petish_Customer_Reviews_UI::nonce( 'submit', $product->get_id() ); ?>
    <fieldset class="pcr-rating-picker"><legend><?php esc_html_e( 'Product quality', 'petish-passport' ); ?> <span class="pcr-required" aria-hidden="true">*</span></legend><div class="pcr-rating-choices"><?php for ( $i = 1; $i <= 5; $i++ ) : ?><label><input type="radio" name="rating" value="<?php echo esc_attr( $i ); ?>" <?php checked( (string) ( $values['rating'] ?? '' ), (string) $i ); ?> required><span aria-hidden="true">★</span><span class="pcr-sr-only"><?php echo esc_html( sprintf( _n( '%d star', '%d stars', $i, 'petish-passport' ), $i ) ); ?></span></label><?php endfor; ?></div><p class="pcr-small" data-pcr-rating-label aria-live="polite"><?php esc_html_e( 'Choose a rating from 1 to 5 stars.', 'petish-passport' ); ?></p></fieldset>
    <label class="pcr-field" for="pcr-alias"><?php esc_html_e( 'Public reviewer name', 'petish-passport' ); ?> <span aria-hidden="true">*</span><input id="pcr-alias" name="alias" maxlength="40" value="<?php echo esc_attr( $values['alias'] ?? '' ); ?>" required aria-describedby="pcr-alias-note" autocomplete="off"></label><p id="pcr-alias-note" class="pcr-field-note"><?php esc_html_e( 'Choose the name others will see. Your billing details and private pet profiles are not used.', 'petish-passport' ); ?></p>
    <label class="pcr-field" for="pcr-title"><?php esc_html_e( 'Give your review a title', 'petish-passport' ); ?> <span aria-hidden="true">*</span><input id="pcr-title" name="title" maxlength="100" value="<?php echo esc_attr( $values['title'] ?? '' ); ?>" required></label>
    <label class="pcr-field" for="pcr-body"><?php esc_html_e( 'Tell us about your experience', 'petish-passport' ); ?> <span aria-hidden="true">*</span><textarea id="pcr-body" name="body" rows="5" maxlength="3000" required><?php echo esc_textarea( $values['body'] ?? '' ); ?></textarea></label>
    <details class="pcr-attachments"><summary><?php esc_html_e( 'Add photos, a video or a reviewer photo', 'petish-passport' ); ?></summary>
        <label class="pcr-field" for="pcr-photos"><?php esc_html_e( 'Product photos', 'petish-passport' ); ?><input id="pcr-photos" type="file" name="photos[]" accept="image/jpeg,image/png,image/webp" multiple data-pcr-photo-files aria-describedby="pcr-photos-note"></label><p id="pcr-photos-note" class="pcr-field-note"><?php esc_html_e( 'Up to 4 JPEG, PNG or WebP photos; 5 MB each. Photo location metadata is removed.', 'petish-passport' ); ?></p>
        <label class="pcr-field" for="pcr-video"><?php esc_html_e( 'Product video', 'petish-passport' ); ?><input id="pcr-video" type="file" name="video" accept="video/mp4" data-pcr-video-file aria-describedby="pcr-video-note"></label><p id="pcr-video-note" class="pcr-field-note"><?php esc_html_e( 'One MP4 video using H.264, up to 20 seconds and 20 MB. Video metadata is retained: remove personal or location information before uploading.', 'petish-passport' ); ?></p>
        <label class="pcr-field" for="pcr-avatar"><?php esc_html_e( 'Your public reviewer photo (optional)', 'petish-passport' ); ?><input id="pcr-avatar" type="file" name="avatar" accept="image/jpeg,image/png,image/webp" data-pcr-avatar-file aria-describedby="pcr-avatar-note"></label><p id="pcr-avatar-note" class="pcr-field-note"><?php esc_html_e( 'JPEG, PNG or WebP, up to 5 MB. This photo will appear beside this review after moderation. Otherwise we show your chosen name’s initial.', 'petish-passport' ); ?></p>
        <p class="pcr-small"><?php esc_html_e( 'Photos, video and your reviewer photo are checked with the review before they become public.', 'petish-passport' ); ?></p>
    </details>
    <label class="pcr-check pcr-consent"><input type="checkbox" name="consent" value="1" required><span><?php esc_html_e( 'This is my genuine experience. I have permission to share these photos and video, and agree that my review, chosen public name and media may be displayed on Petish after moderation.', 'petish-passport' ); ?></span></label>
    <p class="pcr-form-error" data-pcr-file-error role="alert" hidden></p>
    <div class="pcr-submit-row"><button class="pcr-button" type="submit"><?php esc_html_e( 'Submit for moderation', 'petish-passport' ); ?> <span aria-hidden="true">→</span></button><p class="pcr-small"><?php esc_html_e( 'Every honest rating is welcome. Approved reviews count towards status; financial rewards are not active yet.', 'petish-passport' ); ?></p></div>
</form>
